{
  "findings": [
    {
      "title": "Inclusion criterion 4 states age ≥18, but Section 4.1.1 states ≥21 years",
      "page": 43,
      "quote": "Male and female patients must be at least 18 years of age at the time of signing the ICF.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 11 has contradictory hemoglobin requirements: '≥9 g/dL' vs '>8 g/dL' and '≥18 g/dL'",
      "page": 44,
      "quote": "Hemoglobin ≥ 18 g/dL. NOTE: Patients requiring ongoing transfusions or growth factor support to maintain hemoglobin ≥9 g/dL are not eligible. (> 8 g/dL in Gastric Cancer / Gastroesophageal Cancer Indications)",
      "severity": "critical"
    },
    {
      "title": "Exclusion criterion 10 is incomplete and contains an impossible LVEF threshold",
      "page": 48,
      "quote": "10 Lvef at or above 40 %.",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 11 lists 'Hemoglobin ≥ 18 g/dL' which is physiologically implausible and contradicts the preceding text",
      "page": 44,
      "quote": "Hemoglobin ≥ 18 g/dL.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 11 has a formatting error: 'Hemoglobin' row is split and the '≥9 g/dL' requirement is misplaced",
      "page": 44,
      "quote": "Hemoglobin\n≥ 18 g/dL. NOTE: Patients requiring ongoing transfusions or growth factor support to maintain hemoglobin ≥9 g/dL are not eligible.",
      "severity": "major"
    },
    {
      "title": "Inclusion criterion 11 has a stray footnote 'a' without a corresponding footnote in the table",
      "page": 44,
      "quote": "a CLcr (mL/min) = [140 - age (years)] × weight (kg) / 72 × serum creatinine (mg/dL) {× 0.85 for females}",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 12 has an undefined abbreviation 'mBC'",
      "page": 45,
      "quote": "Anti-cancer chemotherapy (Immunotherapy [non-antibody-based therapy]), retinoid therapy, mBC; hormonal therapy: ≥ 3 weeks",
      "severity": "minor"
    },
    {
      "title": "Inclusion criterion 12 has an inconsistent washout for 'small-molecule targeted agents' – '≥ 2 weeks or 5 half-lives' is ambiguous",
      "page": 45,
      "quote": "≥ 2 weeks or 5 half-lives, whichever is longer, for small-molecule targeted agents",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 4 has gender-specific QTcF thresholds that are reversed (females >470, males >450) – typically males have longer QTc",
      "page": 47,
      "quote": "Corrected QT interval by Fridericia's formula (QTcF) prolongation to > 470 msec (females) or > 450 msec (males)",
      "severity": "minor"
    },
    {
      "title": "Exclusion criterion 16 has a typo: 'whole brain radiotherapy' should be 'whole brain radiation' but more importantly the minimum 2 weeks is not specified for stereotactic radiosurgery",
      "page": 48,
      "quote": "A minimum of 2 weeks must have elapsed between the end of whole brain radiotherapy and study enrolment.",
      "severity": "minor"
    },
    {
      "title": "Section 4.1.1 states 'All patients must be ≥ 21 years of age' but inclusion criterion 4 says ≥18 – direct contradiction",
      "page": 40,
      "quote": "All patients must be ≥ 21 years of age (other age restrictions may apply as per local regulations)",
      "severity": "critical"
    },
    {
      "title": "Inclusion criterion 11 has a typo: 'Hemoglobin ≥ 18 g/dL' should likely be '≥ 9 g/dL'",
      "page": 44,
      "quote": "Hemoglobin ≥ 18 g/dL.",
      "severity": "major"
    }
  ]
}
